sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 color3;
uniform float repeat;
uniform float phase;
uniform float reverse;
uniform float scaleBrightness;
uniform float opacity;
uniform float saturation;
uniform float style;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float4 g;
    if (style > 0.5) {
        float x = (reverse > 0.5 ? 1.0 - luma(base) : luma(base)) * repeat + phase;
        float3 d = abs(fract(float3(x, x - 1.0 / 3.0, x - 2.0 / 3.0) + 0.5) - 0.5);
        float3 k = clamp(5.0 / 3.0 - 4.0 * d, 0.0, 1.0);
        g = k.x * float4(color3) + k.y * float4(color2) + k.z * float4(color1);
        g.a = min(g.a, 1.0);
    } else {
        float w = luma(base) * repeat + phase;
        float u = 1.0 - abs(fract(w * 0.5) * 2.0 - 1.0);
        if (reverse > 0.5) u = 1.0 - u;
        g = u < 0.5 ? mix(float4(color1), float4(color2), u * 2.0) : mix(float4(color2), float4(color3), u * 2.0 - 1.0);
    }
    float3 mapped = scaleBrightness > 0.5 ? g.rgb * luma(base) * (style > 0.5 ? 16.0 / 15.0 : 1.0) : g.rgb;
    float grey = luma(mapped);
    mapped = grey + (mapped - grey) * (0.5 + 0.5 * max(saturation, 0.0));
    if (style < 0.5) mapped = clamp(mapped, 0.0, 1.0);
    float3 rgb = mix(base, mapped, clamp(opacity, 0.0, 1.0) * g.a);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
